  about: { title: 'À propos de {{brand}}', seoDesc: 'Découvrez {{brand}}, notre mission, nos valeurs.', whatTitle: 'Ce que nous faisons', whatBody: '{{brand}} est un convertisseur de fichiers en ligne rapide, sécurisé et facile. Nous prenons en chargé plus de 50 formats — documents, images, vidéo, audio, archives.', whyTitle: "Pourquoi nous l'avons créé", whyBody: "Nous etions frustrès par les convertisseurs existants: lents, encombres de pubs, deroutants. Nous avons créé {{brand}} comme l'outil que nous voulions — propre, rapide, respectueux de vos données.", diffTitle: 'Ce qui nous distingue', diff1Title: 'Confidentialité avant tout:', diff1Body: 'Vos fichiers sont automatiquement supprimés après 24 heures. Nous ne lisons, stockons ni partageons votre contenu.', diff2Title: '50+ formats:', diff2Body: 'Documents, images, vidéo, audio, archives et outils PDF — tout au même endroit.', diff3Title: 'Aucune installation:', diff3Body: 'Tout fonctionne dans votre navigateur. Pas de logiciel a télécharger.', diff4Title: 'Traitement par lots:', diff4Body: 'Convertissez plusieurs fichiers à la fois. Téléchargez individuellement ou en ZIP.', diff5Title: 'API développeur:', diff5Body: 'Intégrez la conversion dans vos apps avec notre API REST.', diff6Title: 'Tarification équitable:', diff6Body: 'Démarrez gratuitement, payéz seulement ce que vous utiliséz. Credits sans expiration.', missionTitle: 'Notre mission', missionBody: 'Rendre la conversion de fichiers simple, sécurisée et accèssible a tous. Quelques secondes, jamais des minutes — sans compromettre votre vie privée.', valuesTitle: 'Nos valeurs', privacyTitle: 'Vie privée', privacyBody: 'Vos fichiers vous appartiennent. Nous les traitons, livrons le resultat et supprimons tout en 24 heures.', simplicityTitle: 'Simplicité', simplicityBody: "Pas de confusion. Téléchargez, choisissez un format, téléchargez. C'est tout.", transparencyTitle: 'Transparence', transparencyBody: 'Tarifs clairs, pas de frais caches. Vous savez toujours ce que vous payéz.', qualityTitle: 'Qualité', qualityBody: 'Nous utilisons une technologie de conversion de pointe pour des resultats precis a chaque fois.' },
  faq: { title: 'Questions fréquentes', subtitle: 'Réponses aux questions courantes sur {{brand}}.', seoDesc: 'Questions fréquentes sur {{brand}}. Formats, tarifs, sécurité, limites et plus.', q1: 'Quels formats sont pris en charge?', a1: 'Nous prenons en chargé plus de 50 formats incluant PDF, Word, Excel, PowerPoint, JPG, PNG, WebP, HEIC, SVG, MP4, AVI, MOV, MP3, WAV, FLAC, ZIP, RAR, 7Z et bien plus.', q2: 'Combien de temps mes fichiers sont-ils stockés?', a2: 'Tous les fichiers téléchargés et convertis sont automatiquement supprimés après 24 heures.', q3: 'Est-ce que {{brand}} est gratuit?', a3: 'Les nouveaux utilisateurs reçoivent 1 credit gratuit. Vous pouvez ensuite achétér des packs à partir de €0.99.', q4: 'Comment fonctionne le système de credits?', a4: 'Chaque conversion utilisé 1 credit. Les credits achêtes sont ajoutés instantanement et n expirént jamais.', q5: 'Mes données sont-elles sécurisées?', a5: 'Oui. Tous les transferts utilisént HTTPS. Les fichiers sont supprimés après 24 heures. Nous n accedons jamais a vos contenus.', q6: 'Quelle est la taille maximale?', a6: "Jusqu'à 200 Mo par fichier. Pour plus, contactez-nous au sujet de notre plan Business.", q7: 'A quelle vitesse les conversions se font-elles?', a7: 'La plupart en quelques secondes. Les fichiers volumineux peuvent prendre quelques minutes.', q8: 'Puis-je convertir plusieurs fichiers à la fois?', a8: 'Oui! Glissez-deposez plusieurs fichiers et téléchargez-les separement ou en ZIP.', q9: 'Dois-je créér un compte?', a9: 'Oui, un compte gratuit est requis. Inscription par email ou Google en quelques secondes.', q10: 'Comment obtenir un remboursement?', a10: 'Pour tout problème, contactez-nous dans les 14 jours pour un remboursement complet.', q11: "Puis-je utilisér l'API?", a11: 'Oui! Générez une clé API depuis votre tableau de bord et consultez la documentation.', q12: 'Que se passe-t-il en cas d échec?', a12: "En cas d échec, votre credit n'est pas debite. Réessayez ou contactez-nous." },
  contact: { title: 'Nous contacter', subtitle: "Une question, un commentaire ou besoin d'aide? Envoyéz-nous un message.", seoDesc: 'Contactez {{brand}} pour le support, les commentaires ou les demandes commerciales.', sentTitle: 'Messagé envoyé!', sentBody: 'Merci de nous avoir contacte. Nous répondrons sous 24 heures.', name: 'Nom', email: 'Email', subject: 'Sujet', message: 'Message', send: 'Envoyér le message', sending: 'Envoi...', sentToast: 'Messagé envoyé avec succès!', sendFail: 'Échec de l envoi' },
